def eye(id,short,name,life,role,side,where,lat,lon,vant,vl,form,lang,auth,bio,sources,wp=None):
    d=dict(id=id,short=short,name=name,life=life,role=role,side=side,where=where,lat=lat,lon=lon,vantage=vant,vantage_label=vl,form=form,language=lang,authenticity=auth,bio=bio,sources=[{"title":t,"url":u} for t,u in sources])
    if wp: d["waypoints"]=[{"lat":a,"lon":b,"label":c} for a,b,c in wp]
    return d

eyes=[
eye("tituba","Tituba","Tituba","fl. 1680s–1693","Enslaved woman in the household of the Rev. Samuel Parris, described in the records as 'Indian'; the first of the accused to confess","Salem Village; the Parris household","Parsonage in Salem Village; examined at Ingersoll's ordinary and the meetinghouse; Boston jail from 7 March 1692",42.566,-70.952,0,"accused; the first confessor","court record (examinations as written down by magistrates and a clerk)","English (as recorded by others)","Her words survive only as the questions and answers written down by others: two versions of the 1 March examination (Ezekiel Cheever's and Jonathan Corwin's) and Corwin's record of 2 March. They differ in wording and detail. The originals are among the court papers now at the Phillips Library, Peabody Essex Museum; transcribed in the 1938 WPA typescript (SWP No. 125) and in Rosenthal, Records of the Salem Witch-Hunt (2009).","Nothing certain is known of her birth or origins, and later claims that she was African or that she taught the girls fortune-telling rest on nineteenth-century retellings, not on the 1692 record. Under examination she first denied, then described a tall man from Boston, a book and other women's marks in it. Her confession turned three accusations into a conspiracy. She was never tried: a grand jury refused to indict her in May 1693.",[("SWP No. 125: Tituba (UVA Documentary Archive)","https://salem.lib.virginia.edu/n125.html"),("Examinations recorded by Ezekiel Cheever (Peabody Essex Museum)","https://pem.quartexcollections.com/Documents/Detail/examinations-of-sarah-good-sarah-osburn-and-tituba-as-recorded-by-ezekiel-cheever/3899")],[(42.566,-70.952,"Salem Village, 1–2 March 1692"),(42.358,-71.06,"Boston jail, from 7 March 1692"),(42.679,-70.84,"Ipswich court, May 1693")]),
eye("nurse","Rebecca Nurse","Rebecca Nurse (née Towne)","1621–1692","Aged about 70; a covenanted member of the Salem Town church, mother of eight, wife of the farmer Francis Nurse","Salem Village; the Towne–Nurse family","Her farm in Salem Village; examined in the Village meetinghouse; Salem and Boston jails",42.5636,-70.9581,0,"accused; executed 19 July 1692","court record, petitions and a declaration","English","Her examination of 24 March was written down by Samuel Parris (with Hathorne's and Thomas Newton's hands), and survives with her own petition of 28 June and her declaration of 4 July. Calef printed the declaration in 1700. SWP No. 94; Rosenthal no. 28 and others.","An elderly, half-deaf church member accused by Ann Putnam Jr, Abigail Williams and others, she became the case that troubled even her neighbours: thirty-nine of them signed a petition for her. Her jury first acquitted her, then convicted her after the bench asked it to reconsider. Her sisters Mary Easty and Sarah Cloyce were accused after her.",[("SWP No. 94: Rebecca Nurse (UVA)",SWP),("Examination of Rebecca Nurse (Peabody Essex Museum)","https://pem.quartexcollections.com/Documents/Detail/examination-of-rebecca-nurse/4135")],[(42.5636,-70.9581,"Nurse farm, Salem Village"),(42.566,-70.952,"Examined at the meetinghouse, 24 March"),(42.358,-71.06,"Boston jail, spring 1692"),(42.5195,-70.8967,"Salem jail and trial, June 1692")]),
eye("easty","Mary Easty","Mary Easty (Esty, née Towne)","1634–1692","Aged 58; wife of Isaac Easty, farmer of Topsfield; sister of Rebecca Nurse and Sarah Cloyce","Topsfield; the Towne family","Topsfield; examined at Salem Village; jailed at Ipswich and Salem",42.637,-70.95,0,"accused; executed 22 September 1692","petitions","English","Two petitions survive among the court papers: one with her sister Sarah Cloyce dated 9 September and her own of 15 September 1692, addressed to Governor Phips, the judges and the ministers (Peabody Essex Museum; one hand identified as Stephen Sewall's). Calef printed the second in 1700. SWP No. 45.","Examined on 22 April 1692, she was released in mid-May after the afflicted seemed to clear her, then accused again within days and re-arrested. Her last petition asks nothing for herself; it asks that the judges examine the afflicted apart and test the confessors, so that no more innocent blood be shed.",[("SWP No. 45: Mary Esty (UVA)","https://salem.lib.virginia.edu/n45.html"),("Petition of Mary Esty, 15 Sept 1692 (Peabody Essex Museum)","https://pem.quartexcollections.com/Documents/Detail/1361")],[(42.637,-70.95,"Topsfield"),(42.566,-70.952,"Examined at Salem Village, 22 April"),(42.679,-70.84,"Ipswich jail"),(42.5195,-70.8967,"Salem, trial and execution, September")]),
eye("proctor","John Proctor","John Proctor","1632–1692","Aged about 60; farmer and tavern keeper in Salem Farms; his wife Elizabeth was accused before him","Salem Farms; the accused","Salem prison",42.5195,-70.8967,0,"accused, writing from prison","dated letter","English","His letter 'from Salem-Prison, July 23, 1692', signed for himself and other prisoners and addressed to the Boston ministers (the Mathers, Allen, Moody, Willard and Bailey), survives through Calef's More Wonders (1700), reprinted in Burr (1914).","Proctor had openly scorned the afflicted girls' fits. Arrested in April, he wrote from jail asking that the prisoners' trials be moved to Boston or the judges changed, and reporting that confessions had been forced. He was hanged on 19 August; his pregnant wife was spared.",[("Calef, More Wonders, in Burr, Narratives of the Witchcraft Cases (1914)",BURR)]),
eye("aputnam","Ann Putnam Jr","Ann Putnam Jr","1679–1716","Aged 12 in 1692; daughter of Thomas Putnam, Salem Village landholder and parish clerk","Salem Village; the Putnam family","Salem Village, at examinations and trials",42.57,-70.95,0,"afflicted accuser; later penitent","depositions; a public confession","English","Her 1692 depositions survive among the court papers (for example SWP 94.14, 125.8); many are in her father's handwriting, so her own voice is filtered. Her confession was read aloud in the Salem Village church on 25 August 1706 and copied into the church record by the minister Joseph Green; printed by Upham (1867).","One of the most active accusers, named in dozens of complaints. Fourteen years later, still in Salem Village, she stood while her confession was read: she said she had been deluded by Satan, singled out Rebecca Nurse and her two sisters, and asked forgiveness of the families.",[("Ann Putnam's Confession (1706), text","https://pages.uoregon.edu/mjdennis/courses/wk3_putnam.htm"),("SWP No. 94 (her deposition against Rebecca Nurse)",SWP)]),
eye("parris","Parris","Samuel Parris","1653–1720","Minister of Salem Village since 1689, aged 38; former merchant in Barbados; master of Tituba; father of the afflicted Betty Parris and uncle of Abigail Williams","Salem Village church","Salem Village parsonage and meetinghouse",42.566,-70.952,1,"the minister who wrote things down","sermon notebook, church record book and court depositions","English","His sermon notebook (1689–94, Connecticut Historical Society; ed. Cooper and Minkema, Colonial Society of Massachusetts, 1993) and the Salem Village church record book (transcribed on the UVA archive) survive in his hand; he also acted as scribe at several examinations and signed depositions.","The afflictions began in his house. Parris preached on devils in the church while his neighbours were in jail, took down examinations verbatim, testified at trials, and recorded the excommunication of Martha Corey. Two years later, facing a revolt by the families of the accused, he read 'Meditations for Peace', a partial admission of error. He left the Village in 1697.",[("Sermon of 27 March 1692 (UVA transcription)","https://salem.lib.virginia.edu/sermons/parris16920327a.html"),("Salem Village church record book (UVA)",CHURCH),("Sermon Notebook of Samuel Parris (Colonial Society of Massachusetts)","https://www.colonialsociety.org/node/1465")]),
eye("lawson","Lawson","Deodat Lawson","c. 1647–c. 1727","Former minister of Salem Village (1684–88), by 1692 living in Boston; returned on a visit in March 1692","Boston clergy; former Salem Village minister","Salem Village, 19–24 March 1692",42.566,-70.952,1,"visiting minister, eyewitness","printed narrative with dated entries","English","A Brief and True Narrative of Some Remarkable Passages relating to sundry Persons afflicted by Witchcraft at Salem Village was printed in Boston in 1692 and reprinted in Burr (1914). It is written day by day and names the accused by initials.","Lawson's wife and daughter had died while he was minister at the Village, and in 1692 the afflicted claimed that George Burroughs's spectre had killed them. His narrative is the only eyewitness day-by-day account of the March examinations, written by a believer who records the scenes without doubting the afflicted.",[("A Brief and True Narrative (UVA)","https://salem.lib.virginia.edu/maps/Otherprimarydocuments/a_brief_and_true_narrative.html"),("Excerpt (Hanover College)","https://history.hanover.edu/courses/excerpts/212law.html")],[(42.358,-71.06,"Boston"),(42.566,-70.952,"Salem Village, 19–24 March 1692")]),
eye("sewall","Sewall","Samuel Sewall","1652–1730","Aged 40; Boston merchant, member of the Governor's Council, one of the judges of the Court of Oyer and Terminer","Massachusetts Bay; the bench","Boston; at Salem for examinations, trials and executions",42.358,-71.06,0,"judge","diary","English","His diary, kept from 1673 to 1729, is at the Massachusetts Historical Society and was printed in its Collections (5th series, vols. 5–7, 1878–82). His 1692 entries are brief; the court sessions themselves are barely mentioned.","The only judge of the court who left a diary, and the only one who later apologised in public. His 1692 entries are terse: executions, a fast, a pressing. In January 1697, after the deaths of children in his own family, he stood in his Boston meetinghouse while his minister read his confession of guilt.",[("Sewall's diary, 1692–1697 excerpts (UVA)",SEW),("Sewall diary excerpts (Univ. of Missouri pressbook)",SEW2),("Giles Corey, pressed to death (MHS blog, with the diary page)","https://masshist.org/beehiveblog/2021/09/giles-corey-pressed-to-death")],[(42.358,-71.06,"Boston"),(42.5195,-70.8967,"Salem, court sessions and executions")]),
eye("fisk","Thomas Fisk","Thomas Fisk","fl. 1692","Of Wenham; foreman of the trial jury at Rebecca Nurse's trial","Essex County jurors","Salem courthouse",42.5195,-70.8967,1,"jury foreman","signed declaration; the jurors' joint apology","English","His declaration of 4 July 1692 survives among the court papers (SWP 94.32) and was printed by Calef (1700), with the jurors' later declaration of regret, which Calef prints with the signers' names.","Fisk's statement is the only account from inside a Salem jury of how a verdict was reached: an acquittal, an outcry, a word from the bench, and a reconsidered verdict of guilty. Five years later he and eleven other jurors put their names to a confession that they had been deceived.",[("SWP No. 94 (Fisk declaration, 94.32)",SWP),("Calef, in Burr (1914)",BURR)]),
eye("cmather","Cotton Mather","Cotton Mather","1663–1728","Aged 29; co-minister of Boston's North Church with his father","Boston clergy","Boston; present at the Salem executions of 19 August 1692",42.364,-71.054,2,"minister advising the judges","dated letters and a printed defence of the trials","English","His letters of 1692 (to John Richards 31 May, William Stoughton 2 Sept, Stephen Sewall 20 Sept and others) survive in manuscript and are transcribed on the UVA archive; The Wonders of the Invisible World was printed at Boston in October 1692 and at London in 1693. He drafted the ministers' 'Return' of 15 June.","Mather warned the judges in private against relying on spectral evidence alone, yet urged 'speedy and vigorous' prosecution and then wrote the book that defended the court, using its records. He was at the hanging of George Burroughs. Calef's attack on him in 1700 fixed his reputation for centuries.",[("Letters of Cotton Mather (UVA list)","https://salem.lib.virginia.edu/letters/index.html"),("The Wonders of the Invisible World (Project Gutenberg)",WOND)],[(42.364,-71.054,"Boston, North Church"),(42.5195,-70.8967,"Salem, 19 August 1692")]),
eye("imather","Increase Mather","Increase Mather","1639–1723","Aged 53; minister of Boston's North Church, president of Harvard College; returned from London on 14 May 1692 with the new charter and Governor Phips","Boston clergy","Boston and Cambridge",42.364,-71.054,2,"senior minister, doubter in print","printed treatise","English","Cases of Conscience concerning Evil Spirits Personating Men, dated 'Boston, New-England, Octob. 3. 1692', was printed in Boston and in London (1693) with a postscript defending the judges; reprinted with The Wonders of the Invisible World.","Having chosen the governor and most of the Council, he was the colony's most powerful minister. His treatise did not condemn the court, but it argued that spectral evidence could not prove guilt, and its most famous sentence turned the burden of doubt toward the accused.",[("Cases of Conscience, in The Wonders of the Invisible World (Gutenberg)",WOND)]),
eye("brattle","Brattle","Thomas Brattle","1658–1713","Aged 34; Boston merchant, mathematician and astronomer, treasurer of Harvard College","Boston merchants; critics of the court","Boston",42.358,-71.06,2,"lay critic, writing privately","dated letter","English","A long letter dated 8 October 1692 to an unnamed clergyman, which circulated in manuscript and was first printed in the Collections of the Massachusetts Historical Society (1798); reprinted in Burr (1914).","Brattle wrote as a man of science, demolishing the touch test, the spectral evidence and the value of confessions extracted in prison. He named, with care, the respected men who already disagreed with the court, and he predicted that the stain would outlast his generation.",[("Letter of Thomas Brattle, in Burr (1914)",BURR)]),
eye("phips","Phips","Sir William Phips","1651–1695","Aged 41; royal governor of Massachusetts Bay from May 1692, born on the Maine frontier","the Crown's government","Boston; away on the eastern frontier for much of the summer of 1692",42.358,-71.06,2,"governor who created and ended the court","dated official letters","English","Two letters to London survive: 12 October 1692 (addressed 'Sir') and 21 February 1692/3 to the Earl of Nottingham at Whitehall (received 24 May 1693). Both are printed in Burr (1914).","Phips set up the Court of Oyer and Terminer days after landing, then spent much of the summer on the Indian war in Maine. His letters show him distancing himself: the judges, he wrote, had proceeded while he was away, and he halted both the trials and the printing about them.",[("Two Letters of Gov. William Phips (pressbook)","https://louis.pressbooks.pub/theamericanrevolutionprimarysourcereadings/chapter/two-letters-of-gov-william-phips/"),("Burr, Narratives (1914)",BURR)],[(42.358,-71.06,"Boston"),(43.88,-69.52,"Eastern frontier (Maine), summer 1692")]),
eye("calef","Calef","Robert Calef","1648–1719","Aged 44; Boston cloth merchant","Boston; critics of the Mathers","Boston",42.358,-71.06,2,"hostile chronicler","compiled narrative and dated letters, printed later","English","More Wonders of the Invisible World was printed in London in 1700, since no Boston printer would take it. It combines his 1693–94 letters to Cotton Mather, documents (Proctor's letter, Easty's petition, Fisk's declaration, the jurors' apology, Sewall's bill) and Calef's own narrative of 1692 from witnesses. It is a partisan work written against the Mathers; some details are his alone.","Calef was not an eyewitness to the trials, but he gathered papers and testimony from those who were, and printed them when almost no one else would. His book is the source for several of the most quoted scenes of 1692, which should be read as his report.",[("More Wonders of the Invisible World, in Burr (1914)",BURR)])
]

E=[]
def en(d,disp,prec,eye,place,head,dig,quote,conf,note):
    E.append(dict(date_iso=d,date_display=disp,precision=prec,eye=eye,place=place,headline=head,digest=dig,quote=quote,confidence=conf,source_note=note))

en("1692-03-01","Tuesday 1 March 1691/2 (O.S.)","day","tituba","Salem Village (Ingersoll's ordinary and the meetinghouse)","Tituba first denies, then tells of a tall man and a book","Brought before the magistrates John Hathorne and Jonathan Corwin after Sarah Good and Sarah Osborne, she at first denied hurting the children. Then the record turns: she described a tall man from Boston who told her to serve him, animals that came to her, and Good and Osborne pressing her to hurt the girls. The clerk noted the afflicted grew quieter as she spoke.","","verified","SWP 125.3 (Cheever's record) and 125.4 (Corwin's record), 1 March 1692; summary by Hathorne, 125.2.")
en("1692-03-01","Tuesday 1 March 1691/2 (O.S.)","day","aputnam","Salem Village","A twelve-year-old's deposition against Tituba","The deposition filed in Ann Putnam's name says Tituba's shape pinched and pricked her from late February, and that the torment eased once Tituba began to confess. Like most of her depositions it was written up later, largely in her father Thomas Putnam's hand, and sworn before the court months afterwards.","","approx","SWP 125.8, dated 1 March 1692 in the record; hand and later jurats per Rosenthal (2009).")
en("1692-03-01","Tuesday 1 March 1691/2 (O.S.)","day","parris","Salem Village","The minister swears his girls fell quiet at the confession","Parris, with Thomas Putnam and the clerk Ezekiel Cheever, testified that the afflicted children, his daughter and niece among them, were quieted when Tituba began to confess. The paper carries later notes of 23 May and 28 June, when it was re-used for the court.","","verified","SWP 125.9, deposition of Samuel Parris and others v. Tituba.")
en("1692-03-02","Wednesday 2 March 1691/2 (O.S.)","day","tituba","Salem Village","The second examination: the covenant and the marks","Questioned again, now by Corwin, she described the man who came to her and a book in which she had made her mark, and said she had seen other marks there, including Good's and Osborne's. The magistrates pressed her on how many. On 7 March she and the two women were sent to Boston jail.","","verified","SWP 125.5 (Corwin's record of 2 March) and 125.2 (commitment to Boston, 7 March).")
en("1692-03-19","Saturday 19 March 1691/2 (O.S.)","day","lawson","Salem Village, Parris's house and Ingersoll's","A former minister arrives and sees a girl in a fit","Lawson went first to Parris's house, where he watched Abigail Williams in a fit, then took lodging at Lieutenant Ingersoll's. That evening Mary Walcott, one of the afflicted, came there and showed what she said was a bite on her wrist.","","approx","Lawson, Brief and True Narrative (1692), opening entry; the 19th is as usually cited, the Hanover excerpt does not print the day.")
en("1692-03-20","Sunday 20 March 1691/2 (O.S.)","day","lawson","Salem Village meetinghouse","Abigail Williams interrupts the sermon","At the Sabbath service the afflicted broke into the worship. Abigail Williams ordered Lawson to stand up and name his text, and after the sermon scorned it as having no doctrine. Ann Putnam Sr. and others cried out that they saw a shape on the beam. Lawson records it all as affliction, not as disorder.","Now stand up, and Name your Text","verified","Lawson, Brief and True Narrative (1692); Hanover College excerpt.")
en("1692-03-21","Monday 21 March 1691/2 (O.S.)","day","lawson","Salem Village meetinghouse","Martha Corey before a packed meetinghouse","The magistrates examined 'Goodwife C.', a church member, before a crowd. Asked by Hathorne why she afflicted the children, she answered that she did not know and could not know. The afflicted mimicked her movements; she was committed to Salem prison that afternoon.","I do not know; How should I know?","verified","Lawson, Brief and True Narrative (1692), entry for 21 March; Burr (1914) p. 154.")
en("1692-03-23","Wednesday 23 March 1691/2 (O.S.)","day","lawson","Thomas Putnam's house, Salem Village","Praying over Ann Putnam Sr. in her fit","Lawson visited Thomas Putnam's wife, the mother of Ann Jr., and found her in a fit. He prayed, and she named a chapter of Revelation that she said would drive the apparition off; when it was read she recovered.","","verified","Lawson, Brief and True Narrative (1692); Hanover excerpt.")
en("1692-03-24","Thursday 24 March 1691/2 (O.S.)","day","nurse","Salem Village meetinghouse","Rebecca Nurse: 'nobody to look to but God'","At about ten in the morning the elderly church member was examined by Hathorne and Corwin, with Parris taking it down. Ann Putnam Sr. and the girls cried out; Nurse answered that she was innocent, that she had never afflicted any child, and that she had no one to look to but God. Hathorne observed that the afflicted fell into fits when she moved her hands.","I am as clear as the child unborn","verified","SWP 94.2, Parris's record of the examination; PEM, Rosenthal no. 28. The common version 'innocent as the child unborn' belongs to Israel Porter's statement (94.11), not the examination.")
en("1692-03-24","Thursday 24 March 1691/2 (O.S.)","day","lawson","Salem Village meetinghouse","Lecture day: examination in the morning, sermon after","Lawson saw only part of 'Goodwife N.'s' examination; Hale opened it with prayer. She was committed, and that afternoon Lawson preached the lecture sermon, later printed as Christ's Fidelity the Only Shield against Satan's Malignity, warning the Village that the Devil was among them.","","verified","Lawson, Brief and True Narrative (1692), entry for 24 March; UVA and Hanover texts. Sermon printed Boston 1693.")
en("1692-03-27","Sunday 27 March 1691/2 (O.S.)","day","parris","Salem Village meetinghouse","Sacrament day: 'one of you is a devil'","With two church members now in jail, Parris preached on John 6:70: Christ knows how many devils are in his church, and who they are. The same day he read to the church a testimony against Mary Sibley, who had had Tituba and her husband bake a 'witch cake'; she confessed her ignorance and was kept in fellowship.","","verified","Parris sermon, 27 March 1691/2 (UVA, from the sermon notebook); Salem Village church record, 27 March 1692.")
en("1692-04-11","Monday 11 April 1692 (O.S.)","day","sewall","Salem Town meetinghouse","A judge-to-be watches the afflicted","Sewall travelled to Salem for the examinations of Sarah Cloyce and Elizabeth Proctor, held before the deputy governor and members of the Council. He was shaken by the afflicted, and noted the size of the gathering. It is his first diary mention of the affair.","'twas awfull to see how the afflicted persons were agitated","verified","Sewall, Diary, 11 April 1692 (MHS Collections 5th ser. vol. 5, 1878), UVA excerpts.")
en("1692-05-31","Tuesday 31 May 1692 (O.S.)","day","cmather","Boston","Private advice to a judge on spectral evidence","Two days before the court first sat, Mather wrote to the judge John Richards. He cautioned that the Devil might take the shape of an innocent person, so spectral evidence should not bear more weight than it could carry, and recommended confession and other tests as surer proofs. He did not ask that prosecutions be slowed.","","approx","Letter of Cotton Mather to John Richards, 31 May 1692 (UVA letters list); content summarised from standard editions, the transcription was not consulted directly.")
en("1692-06-10","Friday 10 June 1692 (O.S.)","day","calef","Salem (as Calef later reported)","The first sentence carried out","Calef records that Bridget Bishop, tried on 2 June, was executed on the 10th, the first under the new court. He sets it beside the ministers' 'Return' of 15 June, which he prints in full, to show the advice the judges received after the first death. One of the judges, Nathaniel Saltonstall, left the court about this time.","","approx","Calef, More Wonders (1700), in Burr (1914) p. 356; Saltonstall's departure per standard chronologies.")
en("1692-06-15","Wednesday 15 June 1692 (O.S.)","day","cmather","Boston","The ministers' 'Return': caution, then vigour","Mather drafted the advice of twelve Boston-area ministers to the Governor and Council. Its numbered points urged caution about spectral evidence and the 'touch test', and then closed by recommending that the prosecutions go forward. Critics then and since read the last clause as cancelling the cautions.","speedy and vigorous prosecution","verified","'The Return of Several Ministers', 15 June 1692, printed by Increase Mather (1693) and Calef (1700); Burr p. 356.")
en("1692-06-28","Tuesday 28 June 1692 (O.S.)","day","nurse","Salem jail","Nurse petitions to be searched again","On the eve of her trial Nurse asked the court that other, wiser women examine her body, disputing what the jury of women had reported finding and explaining it as the effect of age and childbirth.","","approx","SWP 94.31, Nurse's petition to the court, 28 June 1692 (date verified; content summarised from standard editions).")
en("1692-06-30","Thursday 30 June 1692 (O.S.)","day","fisk","Salem courthouse","Not guilty, then guilty","The jury under Fisk returned a verdict of not guilty for Rebecca Nurse. The afflicted made an outcry; members of the bench said they were not satisfied and recalled her words about two fellow-prisoners who had testified, 'one of us'. The jury withdrew, she gave no answer when the words were put to her, and they returned guilty. The same session condemned Sarah Good, Susannah Martin, Elizabeth How and Sarah Wildes.","","verified","Fisk's declaration (SWP 94.32, 4 July 1692) and Calef's narrative of the June trials, Burr (1914) pp. 357–359.")
en("1692-07-04","Monday 4 July 1692 (O.S.)","day","fisk","Salem","The foreman explains the verdict","Fisk put in writing why the jury changed its mind: she had called Deliverance and Abigail Hobbs 'one of us', and when asked what she meant she had stayed silent, which the jury took as a strong sign against her.","","verified","SWP 94.32, Declaration of Thomas Fisk, 4 July 1692; printed by Calef.")
en("1692-07-04","Monday 4 July 1692 (O.S.)","day","nurse","Salem jail","'Hard of hearing, and full of grief'","Nurse answered the foreman. By 'one of us' she had meant only that the Hobbses were prisoners alongside her, and she had not answered because, being hard of hearing and full of grief, she had not heard the question. The declaration did not save her. On 3 July, at Salem Town church, Nicholas Noyes had excommunicated her.","something hard of hearing, and full of grief","verified","SWP 94.33, Nurse's declaration, 4 July 1692; printed by Calef (1700), Burr pp. 359–360.")
en("1692-07-19","Tuesday 19 July 1692 (O.S.)","day","calef","Salem (as Calef later reported)","Five hanged; Sarah Good answers the minister","Rebecca Nurse, Sarah Good, Susannah Martin, Elizabeth How and Sarah Wildes were hanged. Calef reports that when Noyes urged Good to confess she was a witch, she answered him that he was lying and that she was no more a witch than he was a wizard. The exchange exists only in Calef's later account.","I am no more a Witch than you are a Wizard","verified","Calef, More Wonders (1700), in Burr (1914) p. 358.")
en("1692-07-23","Saturday 23 July 1692 (O.S.)","day","proctor","Salem prison","A prisoner writes to the Boston ministers","Proctor wrote for himself and other prisoners to the Mathers, Allen, Moody, Willard and Bailey. The accusers, he said, had already condemned them in their own minds; several had confessed only after harsh handling, and his own son had been bound until he bled. He asked that the trials be moved to Boston or the judges changed, and that ministers attend.","very like the Popish Cruelties","verified","Proctor's letter, Salem Prison, 23 July 1692, in Calef (1700); Burr (1914) p. 362.")
en("1692-08-19","Friday 19 August 1692 (O.S.)","day","sewall","Salem, place of execution","Five executed; a minister's verdict","Sewall listed George Burroughs, John Willard, John Proctor, Martha Carrier and George Jacobs as executed at Salem before a very great number of spectators, and noted that Cotton Mather was present. All of them, he wrote, said they were innocent. He recorded Mather's judgment on them without comment of his own.","Mr. Mather says they all died by a Righteous Sentence.","verified","Sewall, Diary, 19 Aug. 1692 (UVA; Missouri pressbook).")
en("1692-08-19","Friday 19 August 1692 (O.S.)","day","calef","Salem (as Calef later reported)","Burroughs says the Lord's Prayer at the end","By Calef's report, George Burroughs, the former Village minister, spoke so well of his innocence and ended by reciting the Lord's Prayer so perfectly that the watching crowd was moved. Cotton Mather, on horseback, then told them the Devil had often been transformed into an angel of light, and the executions went on.","","verified","Calef, More Wonders (1700), in Burr (1914) pp. 360–361. Partisan source; Mather's words are Calef's report.")
en("1692-08-25","Thursday 25 August 1692 (O.S.)","day","sewall","Boston, First Church","A public fast for witchcraft and drought","Sewall noted a fast at the First Church in Boston, held because of the witchcraft, the drought and the colony's other troubles. The routine of a Puritan day of humiliation went on alongside the court.","","verified","Sewall, Diary, 25 Aug. 1692 (UVA excerpts).")
en("1692-09-09","Friday 9 September 1692 (O.S.)","day","easty","Salem prison","Two sisters ask for a fair hearing","With their trials at hand, Mary Easty and Sarah Cloyce petitioned the judges: they were women without counsel and could not plead their own cause, so they asked the judges to be their counsel, to hear witnesses for them, and not to convict on the afflicted's testimony alone. Martha Corey and others were condemned at this session.","","approx","SWP 45.21, joint petition of Mary Esty and Sarah Cloyce, 9 Sept 1692 (date verified; content summarised from standard editions).")
en("1692-09-11","Sunday 11 September 1692 (O.S.)","day","parris","Salem Village church; Salem prison","The church casts out Martha Corey","The church voted to excommunicate Martha Corey, condemned the previous Friday. On 14 September Parris and three church officers went to the prison and pronounced the sentence; Parris recorded that she was impenitent and that the meeting was a sad one.","","verified","Salem Village church record, 11 and 14 Sept. 1692 (UVA).")
en("1692-09-15","Thursday 15 September 1692 (O.S.)","day","easty","Salem prison","'Not for my own life'","Condemned, Easty petitioned Governor Phips, the judges and the ministers. She asked nothing for herself, knowing she must die, but begged that the afflicted be examined apart and the confessors tried closely, so that no more innocent blood would be shed. She would not lie about her own soul, she wrote, by confessing to save herself.","I Petition to your honours not for my own life","verified","SWP 45.22 and PEM, Petition of Mary Esty, 15 Sept. 1692 (Rosenthal 654); printed by Calef (1700).")
en("1692-09-19","Monday 19 September 1692 (O.S.)","day","sewall","Boston (entry about Salem)","Giles Corey pressed to death","Sewall recorded that about noon at Salem Giles Corey, aged about 80, was pressed to death for refusing to put himself on trial. The court and an old acquaintance, Captain Gardner of Nantucket, had tried for two days to persuade him to plead, in vain.","Giles Corey was press'd to death for standing Mute","verified","Sewall, Diary, 19 Sept. 1692; manuscript page shown on the MHS blog.")
en("1692-09-20","Tuesday 20 September 1692 (O.S.)","day","sewall","Boston","A rumour about Corey's past","The day after, Sewall noted news from Salem that Corey had been suspected about eighteen years before of killing a man by stamping on him, and had been cleared. The story came from Thomas Putnam, who wrote that his daughter Ann had been told it by an apparition.","","verified","Sewall, Diary, 20 Sept. 1692 (UVA); Thomas Putnam's letter printed by Calef.")
en("1692-09-20","Tuesday 20 September 1692 (O.S.)","day","cmather","Boston","Asking the court clerk for the trial papers","Mather wrote to Stephen Sewall, the court's clerk and the judge's brother, asking for copies of the trial records so that he could write the account the judges wanted published. The book became The Wonders of the Invisible World.","","approx","Letter of Cotton Mather to Stephen Sewall, 20 Sept. 1692 (UVA letters list); content as commonly summarised.")
en("1692-09-22","Thursday 22 September 1692 (O.S.)","day","calef","Salem (as Calef later reported)","Eight hanged: the last executions","Martha Corey, Mary Easty, Alice Parker, Ann Pudeator, Margaret Scott, Wilmot Redd, Samuel Wardwell and Mary Parker were hanged. Calef reports that Easty's farewell to her husband and children moved those present, and that afterwards Noyes, turning to the bodies, called it a sad thing to see eight firebrands of hell hanging there.","Eight Firebrands of Hell hanging there","verified","Calef, More Wonders (1700), in Burr (1914). Noyes's remark exists only in Calef's report.")
en("1692-09-22","Thursday 22 September 1692 (O.S.)","day","sewall","Sewall's house, Boston","The judges meet to plan a book","That evening William Stoughton, John Hathorne, Cotton Mather and John Higginson met at Sewall's house to discuss publishing an account of the trials. Stoughton left in a storm; the others stayed the night. Sewall wrote nothing of that day's hangings.","","verified","Sewall, Diary, 22 Sept. 1692 (UVA excerpts).")
en("1692-10-03","Monday 3 October 1692 (O.S.)","day","imather","Boston","'Better that ten suspected witches should escape'","Increase Mather finished Cases of Conscience. Spectres, he argued, could take the shape of the innocent, so their appearance proved nothing; neither did the touch test. A postscript insisted he had read and approved his son's book and that the judges deserved pity and prayers, not censure.","better that ten suspected Witches should escape","verified","Cases of Conscience, dated 'Boston, New-England, Octob. 3. 1692' (Gutenberg ed. with Wonders).")
en("1692-10-08","Saturday 8 October 1692 (O.S.)","day","brattle","Boston","A merchant takes the trials apart","Brattle wrote a long letter attacking the court's methods: the touch test, spectral evidence, the use of confessors who had been worked on in prison, and the reliance on the afflicted. He named respected men who disapproved, and blamed 'the Salem Gentlemen' for their credulity. He expected the shame to last for generations.","ages will not wear off that reproach and those stains","verified","Brattle letter, 8 Oct. 1692, in Burr (1914) pp. 167–189.")
en("1692-10-12","Wednesday 12 October 1692 (O.S.)","day","phips","Boston","The governor reports to London and stops the presses","Phips described a 'most Horrible witchcraft or Possession of Devills' that he had found on arrival, and the Devil taking the shape of persons who were doubtless innocent. He had stopped further committals except in unavoidable necessity, suspended the court until the King's pleasure was known, and forbidden printing on the subject.","I have also put a stop to the printing","verified","Phips letter, 12 Oct. 1692, Burr (1914) p. 196; pressbook transcription.")
en("1692-10-15","Saturday 15 October 1692 (O.S.)","day","sewall","Cambridge","An old magistrate's doubt","Sewall visited the former deputy governor Thomas Danforth, who told him the court could not go on without better agreement among the ministers and the people. Sewall recorded it without comment.","","verified","Sewall, Diary, 15 Oct. 1692 (UVA excerpts).")
en("1692-10-26","Wednesday 26 October 1692 (O.S.)","day","sewall","Boston, General Court","The vote that ended the court","Sewall recorded a bill in the General Court for a fast and a convocation of ministers to advise on the witchcraft, passed 33 to 29. He noted that it amounted to dismissing the Court of Oyer and Terminer. Phips dissolved the court three days later.","","verified","Sewall, Diary, 26 Oct. 1692 (UVA excerpts); court dissolved 29 Oct. per standard chronologies.")
en("1692-10","October 1692 (O.S.)","month","cmather","Boston","The Wonders of the Invisible World","Mather's book appeared in Boston with a commendation by William Stoughton, the chief judge. It summarised five of the trials from the court papers, including those of George Burroughs, Bridget Bishop and Martha Carrier, and framed the outbreak as a Devil's assault on New England. It was reprinted in London in 1693.","","verified","Wonders of the Invisible World, Boston Oct. 1692, London 1693 (Gutenberg ed. and introduction).")
en("1693-02-21","Tuesday 21 February 1692/3 (O.S.)","day","phips","Boston","The governor's account of the ending","Writing to the Earl of Nottingham, Phips summed up: the first court had condemned some twenty people, some of whom he thought innocent; he had found at least fifty in prison, most held on spectral evidence alone. The new Superior Court tried fifty-two and condemned three, and he had reprieved those it sentenced. He blamed the chief judge, Stoughton, who had left the bench in anger.","only spectre evidence against them","verified","Phips letter to the Earl of Nottingham, 21 Feb. 1692/3, received 24 May 1693; Burr (1914) p. 198; pressbook.")
en("1693-05-09","Tuesday 9 May 1693 (O.S.)","day","tituba","Ipswich court","No bill: Tituba's case ends","At the Court of Assize at Ipswich the grand jury returned 'ignoramus' on the indictment charging Tituba with a covenant with the Devil, and she was never tried. Calef later reported that she was sold to pay her prison fees; nothing more of her is recorded with certainty.","","verified","SWP 125.6, indictment returned ignoramus, 9 May 1693; Calef (1700) for the sale, which rests on his report.")
en("1693-09-29","Friday 29 September 1693 (O.S.)","day","calef","Boston","The merchant challenges the minister","After attending Cotton Mather's visit to Margaret Rule, a young Boston woman said to be afflicted, Calef had circulated notes of what he saw. Mather took offence. In a letter of 29 September Calef defended his account and asked to discuss the questions of witchcraft openly. It began the correspondence he later printed.","","verified","Calef's letter of 29 Sept. 1693 to Cotton Mather, More Wonders (1700), Burr (1914) pp. 324–340.")
en("1694-11-26","Monday 26 November 1694 (O.S.)","day","parris","Salem Village meetinghouse","'Meditations for Peace'","After two years in which the families of the accused, among them Rebecca Nurse's son and her brothers-in-law Peter Cloyce and John Tarbell, refused his communion, Parris heard their reasons in writing and then read his 'Meditations for Peace'. He allowed that he might have trusted spectral evidence too far and asked forgiveness of those he had wronged, while keeping his post.","","verified","Salem Village church record, 26 Nov. 1694; 'Meditations' dated 29 Nov. (UVA).")
en("1697-01-14","Thursday 14 January 1696/7 (O.S.)","day","sewall","Old South Meetinghouse, Boston","The judge stands while his guilt is read","On the colony's day of fasting for its errors, Sewall handed a written bill to his minister Samuel Willard as he passed, and stood while it was read. He acknowledged the guilt he had contracted at the Salem court and desired to take the blame and shame of it, asking pardon of God and men.","Desires to take the Blame and shame of it","verified","Sewall, Diary, Jan. 1696/7 (bill copied into the diary); fast of 'Thursday the Fourteenth of January' per Calef.")
en("1697-01","January 1696/7 (O.S.)","month","fisk","Essex County","Twelve jurors confess their error","Fisk and eleven other jurors signed a declaration that they had been under a strong and general delusion and had condemned people on insufficient evidence, for want of knowledge in themselves. They asked forgiveness of the living sufferers and the families of the dead, and said they would not do the like again.","for want of Knowledge in our selves","approx","Jurors' declaration, printed by Calef (1700), Burr (1914); month as usually given, Calef prints no day.")
en("1700","1700","year","calef","London","More Wonders reaches print","Calef's book was printed in London. It printed what the trial papers and the accused had said, and argued that the Mathers had driven the panic. In Boston Increase Mather is said to have had the book burned in Harvard Yard, and the Mathers' supporters replied in print in 1701.","","approx","Calef, More Wonders of the Invisible World (London, 1700); the burning and the reply are as usually reported.")
en("1706-08-25","Sunday 25 August 1706 (O.S.)","day","aputnam","Salem Village meetinghouse","Ann Putnam's confession is read","Now 26, an orphan seeking admission to the church, Ann Putnam stood while the minister Joseph Green read her confession. She said she had been made an instrument, through a great delusion of Satan, to accuse innocent people, especially Goodwife Nurse and her two sisters, and that she did it out of ignorance rather than anger. She asked forgiveness of the families she had wronged.","a great delusion of Satan","verified","Confession of 25 Aug. 1706, Salem Village church record, signed J. Green; printed by Upham (1867).")
en("1711-10-17","Wednesday 17 October 1711 (O.S.)","day","sewall","Boston, General Court","The attainders reversed","The General Court, in which Sewall sat as a councillor, passed an act declaring the convictions of twenty-two named people null and void, among them Rebecca Nurse, Mary Easty, John Proctor and Giles Corey. Those whose families had not petitioned were left out. The governor later ordered £578 12s. paid to survivors and heirs.","null and void to all Intents, Constructions and purposes whatsoever","verified","Act of 17 Oct. 1711 (text on uoregon.edu); compensation total from the same page.")

