dict(date="1692-08-19",label="Five executed at Salem",eyes=["sewall","calef","cmather"],note="The judge's diary records Mather's approval; the hostile chronicler records the crowd moved by Burroughs's prayer and Mather calming them. Mather's own account of Burroughs went into his book weeks later."),
